#ifndef ENC_IMAGE_KEY_H_
#define ENC_IMAGE_KEY_H_

#include <stdint.h>

/*
 * Device private key record (image decryption) sits in the tail of the boot partition.
 * Size fixed with ENC_KEY_AREA_SIZE bytes to currently to 0x100 / 256 bytes. Header + key in DER format requires 56 bytes today.
 * Build hex file for the key is generated by nrf-bm/scripts/generate_enc_key.py, keep in sync with this file. 
 * The firmware loader only reads the record, it does not reserve it. Build tool mergehex will fail on overlapping areas.
 * 
 */

#define ENC_KEY_AREA_SIZE 0x100

/** "ENCK" in memory. */
#define ENC_KEY_RECORD_MAGIC 0x4b434e45

struct enc_key_record {
	uint32_t magic;
	/** Length of the DER encoded key in bytes, read by MCUboot through a pointer. */
	uint32_t len;
	/** X25519 private key, PKCS#8 DER as printed by imgtool getpriv. */
	uint8_t der[];
};

#endif /* ENC_IMAGE_KEY_H_ */
